def f_row(g):
    H,W=len(g),len(g[0])
    rowC={}
    for r in range(H):
        nz={v for v in g[r] if v}
        if len(nz)==1: rowC[r]=nz.pop()
    if not rowC: return None
    P=len(rowC); pos=sorted(rowC)
    h=[];used=[False]*P
    for k,v in sorted(rowC.items()):
        cls=k%P
        if used[cls]: continue
        h.append(v); used[cls]=True
        # fill other residues whose first line hit a used residue
        while True:
            found=False
            for i in range(P):
                s2=(cls+i)%P
                if not used[s2]:
                    h.append(v); used[s2]=True; found=True; break
            if not found: break
    return [[h[(r-pos[0])%P] for _ in range(W)] for r in range(H)]

