    P=len(coords); pos=sorted(coords)
    h=[];used=[False]*P
    for k,v in sorted(coords.items()):
        cls=k%P
        if used[cls]: continue
        val=v[0]; h.append(val); used[cls]=True
        while True:
            found=False
            for i in range(P):
                s2=(cls+i)%P
                if not used[s2]:
                    h.append(val); used[s2]=True; found=True; break
            if not found: break
    return [[h[((c-r)-pos[0])%P] for c in range(W)] for r in range(H)]
